"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([["35369"],{74408(e){e.exports=JSON.parse('{"tag":{"label":"Hedgehogs","permalink":"/docs/tags/hedgehogs","allTagsPath":"/docs/tags","count":28,"items":[{"id":"general-care/health-and-medical/skin-issues","title":"A Guide to Common Skin Issues in Small Pets","description":"A comprehensive guide to identifying, preventing, and treating common skin problems in small exotic pets, including urine scald, mites, ringworm, and bacterial infections, with species-specific advice.","permalink":"/docs/general-care/health-and-medical/skin-issues"},{"id":"Hedgehogs/illnesses-and-conditions/acariasis","title":"Acariasis (Mite Infestation) in Hedgehogs","description":"An in-depth guide to acariasis (mite infestation) in hedgehogs, the most common skin disease in the species, covering signs like quill loss, diagnosis, and effective treatment.","permalink":"/docs/Hedgehogs/illnesses-and-conditions/acariasis"},{"id":"Hedgehogs/illnesses-and-conditions/common-health-issues","title":"Common Health Issues in Hedgehogs","description":"An overview of the most common health issues affecting pet hedgehogs, including the devastating Wobbly Hedgehog Syndrome (WHS), their high incidence of cancer, and common problems like obesity and parasites.","permalink":"/docs/Hedgehogs/illnesses-and-conditions/common-health-issues"},{"id":"general-care/safety/dangerous-plants","title":"Dangerous Plants for Small Pets: A Regional Guide","description":"Global dangerous plants infographic","permalink":"/docs/general-care/safety/dangerous-plants"},{"id":"Hedgehogs/health-and-wellness/dental-health","title":"Dental Health in Hedgehogs","description":"A guide to dental health in hedgehogs, covering common problems like gingivitis, tartar, fractured teeth, and the high risk of oral cancers like squamous cell carcinoma.","permalink":"/docs/Hedgehogs/health-and-wellness/dental-health"},{"id":"Hedgehogs/illnesses-and-conditions/diabetes-in-hedgehogs","title":"Diabetes in Hedgehogs","description":"A comprehensive guide to diabetes in hedgehogs \u2014 causes, signs, diagnosis, and management strategies for this common metabolic condition.","permalink":"/docs/Hedgehogs/illnesses-and-conditions/diabetes-in-hedgehogs"},{"id":"Hedgehogs/care-and-husbandry/essential-supplies","title":"Essential Supplies for Pet Hedgehogs","description":"A complete checklist of the essential supplies needed to set up a safe, warm, and stimulating environment for a pet hedgehog.","permalink":"/docs/Hedgehogs/care-and-husbandry/essential-supplies"},{"id":"Hedgehogs/health-and-wellness/eye-and-vision-issues","title":"Eye & Vision Issues in Hedgehogs","description":"A guide to common eye and vision issues in hedgehogs, including infections, injuries, and the risk of eye proptosis (prolapse).","permalink":"/docs/Hedgehogs/health-and-wellness/eye-and-vision-issues"},{"id":"Hedgehogs/health-and-wellness/gi-health","title":"Gastrointestinal (GI) Health in Hedgehogs","description":"A guide to gastrointestinal (GI) health in hedgehogs, covering their unique dietary needs as insectivores and the common causes of digestive upset.","permalink":"/docs/Hedgehogs/health-and-wellness/gi-health"},{"id":"Hedgehogs/care-and-husbandry/grooming","title":"Grooming Your Pet Hedgehog","description":"A guide to the essential grooming needs of a pet hedgehog, including how to give them a bath and trim their nails safely.","permalink":"/docs/Hedgehogs/care-and-husbandry/grooming"},{"id":"Hedgehogs/illnesses-and-conditions/heart-disease","title":"Heart Disease in Hedgehogs","description":"A guide to heart disease in hedgehogs, particularly Dilated Cardiomyopathy (DCM), a common condition in the species, covering its signs, diagnosis, and management.","permalink":"/docs/Hedgehogs/illnesses-and-conditions/heart-disease"},{"id":"Hedgehogs/getting-started/hedgehog-basic-care","title":"Hedgehog Basic Care","description":"Hedgehogs are unique and charming pets, but they have very specific care needs that are critical to their survival and well-being. Unlike more common small pets, they are not low-maintenance and require a dedicated owner to thrive. This guide covers the essential aspects of hedgehog care.","permalink":"/docs/Hedgehogs/getting-started/hedgehog-basic-care"},{"id":"Hedgehogs/care-and-husbandry/habitat","title":"Hedgehog Habitat","description":"Creating a safe, warm, and stimulating habitat is the most important part of hedgehog ownership. Their enclosure is their entire world, and it must be set up to meet their unique needs, especially...","permalink":"/docs/Hedgehogs/care-and-husbandry/habitat"},{"id":"Hedgehogs/care-and-husbandry/nutrition","title":"Hedgehog Nutrition","description":"Hedgehogs are insectivores, meaning their natural diet consists primarily of insects. In captivity, their diet is based on a high-quality, low-fat cat food, supplemented with insects and other...","permalink":"/docs/Hedgehogs/care-and-husbandry/nutrition"},{"id":"Hedgehogs/care-and-husbandry/wheels-essential","title":"Hedgehog Wheels: Why They\'re Essential and How to Choose One","description":"A complete guide to hedgehog running wheels \u2014 why they are a non-negotiable welfare requirement, minimum size recommendations, surface safety, and daily cleaning needs.","permalink":"/docs/Hedgehogs/care-and-husbandry/wheels-essential"},{"id":"Hedgehogs/health-and-wellness/home-health-care","title":"Home Health Care for Pet Hedgehogs","description":"A guide to performing regular at-home health checks for your pet hedgehog to monitor their well-being and catch early signs of illness.","permalink":"/docs/Hedgehogs/health-and-wellness/home-health-care"},{"id":"general-care/daily-care/introductions-and-bonding","title":"Introductions and Bonding","description":"How to safely introduce small pets to each other \u2014 covering quarantine, scent swapping, neutral space introductions, and warning signs for all HALT species.","permalink":"/docs/general-care/daily-care/introductions-and-bonding"},{"id":"Hedgehogs/getting-started/is-a-hedgehog-right-for-me","title":"Is a Hedgehog Right for Me and My Family?","description":"Hedgehogs are unique, fascinating animals with big personalities packed into a small, spiny package. They are not cuddly in the traditional sense \u2014 most hedgehogs take time to warm up to handling,...","permalink":"/docs/Hedgehogs/getting-started/is-a-hedgehog-right-for-me"},{"id":"Hedgehogs/health-and-wellness/parasites","title":"Parasites in Hedgehogs","description":"A guide to parasites affecting hedgehogs, with a focus on the common and serious problem of mite infestations, as well as the fungal infection ringworm.","permalink":"/docs/Hedgehogs/health-and-wellness/parasites"},{"id":"Hedgehogs/care-and-husbandry/playing-and-training","title":"Playing with and Training Your Hedgehog","description":"Hedgehogs are solitary, nocturnal explorers that need nightly enrichment and exercise. Learn how to engage your hedgehog\'s natural instincts and build a bond through gentle handling and simple training.","permalink":"/docs/Hedgehogs/care-and-husbandry/playing-and-training"},{"id":"general-care/health-and-medical/pneumonia-in-small-pets","title":"Pneumonia in Small Pets","description":"A general guide to pneumonia in small pets, covering causes, species-specific signs, diagnosis, treatment, and prevention for rabbits, rats, ferrets, chinchillas, hamsters, gerbils, hedgehogs, mice, and degus.","permalink":"/docs/general-care/health-and-medical/pneumonia-in-small-pets"},{"id":"Hedgehogs/care-and-husbandry/proper-handling","title":"Proper Handling of Pet Hedgehogs","description":"A guide to safely and confidently handling a pet hedgehog, with tips for building trust and getting past their spiky defenses.","permalink":"/docs/Hedgehogs/care-and-husbandry/proper-handling"},{"id":"Hedgehogs/health-and-wellness/respiratory-issues","title":"Respiratory Issues in Hedgehogs","description":"A guide to respiratory infections in hedgehogs, covering the common causes, signs of illness, and the importance of prompt veterinary care.","permalink":"/docs/Hedgehogs/health-and-wellness/respiratory-issues"},{"id":"general-care/daily-care/safe-treats","title":"Safe Treats for Small Pets","description":"A comprehensive guide to safe and unsafe treats for all small pet species, including rabbits, guinea pigs, rats, hamsters, gerbils, chinchillas, ferrets, hedgehogs, mice, and degus.","permalink":"/docs/general-care/daily-care/safe-treats"},{"id":"Hedgehogs/breeds-and-genetics/sexing-your-hedgehog","title":"Sexing Your Pet Hedgehog","description":"A simple guide to determining the sex of a pet hedgehog by identifying the key anatomical differences between males and females.","permalink":"/docs/Hedgehogs/breeds-and-genetics/sexing-your-hedgehog"},{"id":"general-care/daily-care/outdoor-safety","title":"Taking Your Small Pet Outside Safely","description":"Outdoor safety infographic for small pets","permalink":"/docs/general-care/daily-care/outdoor-safety"},{"id":"Hedgehogs/health-and-wellness/understanding-hedgehog-behavior","title":"Understanding Hedgehog Behavior: A Guide for Owners","description":"Hedgehogs are unique and fascinating creatures with a set of behaviors all their own. As solitary and nocturnal animals, their communication is often quiet and defensive...","permalink":"/docs/Hedgehogs/health-and-wellness/understanding-hedgehog-behavior"},{"id":"Hedgehogs/illnesses-and-conditions/wobbly-hedgehog-syndrome","title":"Wobbly Hedgehog Syndrome (WHS)","description":"An in-depth guide to Wobbly Hedgehog Syndrome (WHS), a progressive, degenerative neurological disease in hedgehogs, covering its signs, progression, and the current understanding of the condition.","permalink":"/docs/Hedgehogs/illnesses-and-conditions/wobbly-hedgehog-syndrome"}],"unlisted":false}}')}}]);